raw_response:
{
  "background": "（推断）来访者是一位成年人，可能处于工作或社交环境中，与家人关系密切，对外界有较强的情绪管理需求。",
  "self_view_of_problem": "我觉得我和外人基本不会表达一点点的愤怒，委屈登登。等等。和自己的家人又太过了。对外人表达，我好像怕别人承受不了。在我看来愤怒就是很大的事…从没觉得有程度，和别人生气是很大的事…没想过一点点愤怒。",
  "resistance_drivers": [
    "（推断）当咨询师将情绪表达（如撒娇）正常化或技能化时，来访者可能通过沉默（如'嗯'）或强调愤怒的严重性来阻抗，维持其'愤怒是大事'的认知框架。",
    "（推断）当讨论情绪表达的'程度'或'一点点'可能性时，来访者可能通过重申'没想过一点点愤怒'来阻抗，保护其非黑即白的情绪认知。"
  ],
  "ambivalence": {
    "for_change": "（推断）渴望能更自由、适度地表达情绪，尤其是对外人，以避免委屈积累和潜在的'火山爆发'。",
    "against_change": "（推断）恐惧情绪表达（尤其是愤怒）会破坏关系或对他人造成不可承受的伤害，从而威胁到自我作为'克制、为他人着想'的认同。"
  },
  "values_and_stakes": [
    "（推断）改变可能失去与外人相处时'情绪稳定、不惹事'的安全角色和表面和谐。",
    "（推断）改变可能失去在家庭中作为可以过度宣泄情绪的'安全出口'的特权位置。",
    "（推断）改变可能失去'愤怒是大事'这一认知所维护的内在秩序感和道德优越感（认为自己克制是高尚的）。"
  ],
  "key_facts": [
    "来访者对外人基本不会表达一点点的愤怒。",
    "来访者对自己的家人情绪表达又太过了。",
    "来访者认为和别人生气是很大的事，从没想过可以有一点点愤怒。"
  ]
}

{
  "background": "（推断）来访者可能从事或接触过人工智能、对话系统或客服相关工作，例如曾参与天猫精灵等智能助手的开发或测试，对对话流程和话术设计有专业认知。",
  "self_view_of_problem": "（推断）来访者认为当前咨询对话效率低下，咨询师的回应像预设的兜底话术，缺乏引导多轮深入对话的能力，导致沟通无法有效推进。",
  "resistance_drivers": [
    "当咨询师尝试理解或定义来访者使用的概念（如‘奔放’）时，来访者会通过将咨询师比作AI、批评其话术生硬和效率低下来表达阻抗，表现出对咨询师专业能力的质疑和对话过程的不满。",
    "（推断）当咨询师的回应方式（如重复来访者的话‘兜底话术，这个描述有些意思’）显得被动或缺乏深度引导时，会触发来访者指出对话效率问题，表现出对咨询进程缺乏进展的挫败感。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者渴望获得更高效、能引导多轮深入对话的咨询体验，这表明他内心希望咨询能真正帮助他解决问题。",
    "against_change": "（推断）来访者对咨询师持怀疑和批评态度，可能隐含对敞开心扉、依赖他人引导的情感抵触或对改变现状的潜在不安。"
  },
  "values_and_stakes": [
    "（推断）改变（如接纳当前咨询方式）可能使来访者失去基于自身专业背景（如对话系统设计）建立的批判视角和控制感。",
    "（推断）改变可能使来访者失去通过质疑和保持距离来维护的心理安全感或优越感。"
  ],
  "key_facts": [
    "来访者曾参与过天猫精灵里的答复相关工作。",
    "来访者明确批评当前对话效率很低。",
    "来访者将咨询师的大部分话术类比为AI的兜底话术。"
  ]
}

{
  "background": "（推断）来访者是一位成年人，可能处于工作或家庭压力较大的生活阶段，近期经历了需要长时间恢复的困难事件。",
  "self_view_of_problem": "我觉得自己缓了两个月了，但改变的时间太长，让我心力交瘁，想快点回到之前有能量、自信的状态。",
  "resistance_drivers": [
    "当咨询师将问题归因于‘最近发生太多事，让你有些累了’并建议‘放松下来等一等’时，来访者通过强调‘我都缓了两个月了’来反驳，表现出对咨询师将问题轻描淡写或建议被动等待的不耐烦。",
    "（推断）当咨询师未能立即回应或来访者感到对话节奏不符合其急切改变的期望时（如‘你还在吗’），会表现出对咨询师关注度或有效性的质疑。"
  ],
  "ambivalence": {
    "for_change": "（推断）渴望摆脱心力交瘁的状态，重新获得自信和活力。",
    "against_change": "（推断）对‘缓了两个月’仍无进展感到疲惫和挫败，这种挫败感本身消耗了改变的能量。"
  },
  "values_and_stakes": [
    "（推断）改变可能意味着要放弃或挑战过去两个月里已经形成的、虽然痛苦但可能熟悉的应对模式或休息状态。",
    "（推断）快速‘回到之前的状态’的压力，可能使其面临无法达到自我预期而再次失望的风险。"
  ],
  "key_facts": [
    "来访者认为自己已经‘缓了两个月’但感觉没有足够进展。",
    "来访者在对话中曾短暂体验到‘很自信，有力量’的感觉。",
    "来访者在咨询师短暂未回应时发出了‘你还在吗’的询问。"
  ]
}

{
  "background": "（推断）来访者是一名在国内工作的职场人士，目前可能处于居家办公或隔离状态，工作环境受疫情影响存在不确定性。",
  "self_view_of_problem": "在家没什么氛围，效率低，还不如不工作，发发呆都是好的；工作要有产出，只是走形式，没有意义，浪费时间。",
  "resistance_drivers": [
    "当咨询师将问题归因于外部共识（如‘既然大家都这么认为’）时，来访者会立即反驳，并强调问题在于自身的内在感受和效率低下。",
    "（推断）当咨询师试图将来访者的行为解读为对‘结果’的注重时，来访者会转移话题，转而强调其他活动（如睡觉、打游戏）的优越性，以此回避对工作态度或效率的深入探讨。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者内心可能承认在家工作效率低下是一种问题状态，并隐含了对更高效率或更有意义产出的潜在渴望。",
    "against_change": "（推断）来访者内心依恋于在家时‘不工作’所带来的自由、放松和低压力状态，将其视为一种优于‘无意义工作’的合理选择。"
  },
  "values_and_stakes": [
    "（推断）改变（即在家认真工作）可能会失去在家环境中自由安排时间、进行休闲活动（如睡觉、打游戏、看电影、看书）的轻松感和掌控感。",
    "（推断）改变可能会失去当前对‘无意义工作形式’的消极抵抗所维持的心理舒适区，需要面对产出压力和可能的失败。"
  ],
  "key_facts": [
    "来访者认为在家工作没什么氛围，效率低。",
    "来访者觉得在家睡觉、打游戏、看电影、看书都比工作好很多。",
    "来访者提到工作要有产出，只是走形式没有意义。"
  ]
}

{
  "background": "（推断）来访者从事医学或相关领域工作，对跨学科研究感兴趣，可能在工作中需要解读他人的困惑。",
  "self_view_of_problem": "（推断）来访者可能感到自己的职业选择或人生方向存在某种困惑或不确定性，潜意识在引导自己，但自己尚未完全理解其意义。",
  "resistance_drivers": [
    "（推断）当咨询师直接解读来访者的潜意识动机（如'潜意识一直照顾着自己'）时，来访者会以疑问句（'是这样的吗'）表达不确定和轻微的质疑，表现出对直接解释的谨慎接受。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者渴望理解自己人生经历和选择的深层意义，希望从困惑中获得清晰感。",
    "against_change": "（推断）来访者对'潜意识引导'这一解释本身存在不确定感，可能隐含对失去自主掌控感的担忧。"
  },
  "values_and_stakes": [
    "（推断）改变（即完全接受潜意识引导的解释）可能意味着失去对自身职业和人生路径的理性规划和自主掌控感。"
  ],
  "key_facts": [
    "来访者对医学的感觉是'很微妙'。",
    "来访者询问'我的潜意识在帮我做选择吗'。",
    "来访者对咨询师关于'生命需要的课程'的表述回应为'或许是的'。"
  ]
}

{
  "background": "（推断）从事心理咨询或相关行业约10年，目前可能面临职业瓶颈或倦怠，对行业运作模式（如多窗口回复）有一定了解。",
  "self_view_of_problem": "（推断）我把当前的工作困境看作一个‘持续太久的瓶颈期’，虽然以前也有过类似困难并成功度过，但这次持续时间过长让我感到不安，甚至用‘挺好玩儿的’这种轻松化表述来掩饰焦虑。",
  "resistance_drivers": [
    "当咨询师试图聚焦于具体问题（如询问从业时长）时，来访者会转移话题到咨询设置或行业八卦（如询问入职、兼职、多窗口回复），表现出回避深入探讨自身问题的倾向。",
    "（推断）当对话可能触及对自身职业困境的严肃反思时，来访者会使用‘哈哈’、‘挺好玩儿的’等轻松化或玩笑语气，将问题最小化，避免暴露脆弱感。"
  ],
  "ambivalence": {
    "for_change": "（推断）我隐约承认这个‘瓶颈期’持续太久了，这让我感到不安，说明内心有一部分渴望摆脱这种停滞状态。",
    "against_change": "（推断）我内心依恋于‘这只是个暂时的瓶颈期’这个熟悉的、过去曾有效的自我安慰叙事，改变意味着要面对可能更严峻的职业现实或自我怀疑。"
  },
  "values_and_stakes": [
    "（推断）改变可能意味着失去‘过去能成功度过困难期’的自我效能感和‘这只是瓶颈期’的乐观叙事所提供的心理保护。",
    "（推断）深入探讨问题可能威胁到来访者作为从业者（可能也是帮助者）的专业身份认同，暴露出自己也需要帮助的脆弱面。"
  ],
  "key_facts": [
    "来访者在本行业已工作10年。",
    "来访者提到‘平安医生心理科’过去采用‘一个人后台好几个窗回复’的模式。",
    "来访者主动询问咨询师所在平台的入职要求和兼职岗位。"
  ]
}

{
  "background": "（推断）来访者是一名职场人士，工作压力大，经常加班熬夜，处于高负荷的工作状态中。",
  "self_view_of_problem": "来访者认为加班熬夜带来的压力是“很正常”的，并且觉得“说了也没用”，认为“改变也没什么意义”，所以选择“熬着就行了”。",
  "resistance_drivers": [
    "当咨询师提出可以尝试调整或改变时，来访者会立刻以极端化的方式（如“辞职吗？那更不可能”）来否定可能性，并最终以“算了吧”来结束话题。",
    "（推断）当咨询师试图挑战或质疑其“压力正常化”的认知时，来访者会以“说了也没用”的无力感和宿命论来回避深入探讨。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者内心可能承认这种疲惫的状态并不好，否则不会前来咨询。",
    "against_change": "来访者对现状有强烈的宿命感和无力感，认为任何改变都是无意义的，并依恋于“熬着”这种看似可控的应对方式。"
  },
  "values_and_stakes": [
    "（推断）改变可能会失去目前的工作职位或稳定的收入来源。",
    "（推断）改变可能会破坏其作为“能吃苦、能扛事”的职场人自我认同或社会角色。"
  ],
  "key_facts": [
    "来访者认为加班熬夜是正常现象。",
    "来访者认为向他人诉说自己的压力是没用的。",
    "来访者认为改变现状是没有意义的。"
  ]
}

{
  "background": "（推断）来访者是一位成年人，与父母同住或关系密切，目前面临与父母沟通的困难。",
  "self_view_of_problem": "（推断）来访者认为自己的问题是向父母表达内心感受有困难，这可能是导致父母过度操心的原因之一。",
  "resistance_drivers": [
    "当咨询师提出具体行动建议（如向父母表达感受）时，来访者会以‘感觉困难’或‘可能是一种方式’等模糊、保留的措辞来回应，表现出对改变的犹豫和阻抗。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者内心希望父母能减少对自己的操心，并希望父母能感受到自己已经长大。",
    "against_change": "（推断）来访者对直接向父母表达内心感受感到不适和困难，这种不适感阻碍了改变。"
  },
  "values_and_stakes": [
    "（推断）改变（即向父母表达感受）可能会失去目前与父母相处中某种熟悉的、尽管可能不理想的平衡状态。"
  ],
  "key_facts": [
    "来访者在咨询快结束时会产生一种未具体说明的‘感觉’。",
    "来访者不记得是提到哪个具体部分时产生了那种感觉。",
    "来访者承认向父母表达内心感受对自己来说‘会有点困难’。"
  ]
}

{
  "background": "（推断）来访者是一名在职人员，工作单位存在人员短缺问题，有一位鼓励他的科长。",
  "self_view_of_problem": "来访者认为自己的问题是‘自我精神内耗，自我焦虑’，导致失眠、没精打采，并且在工作上感觉困难，尽管同事认为工作不难。",
  "resistance_drivers": [
    "当咨询师试图肯定其能力或潜力时（如提到‘数学是绝对优势’、‘做了不少尝试’），来访者会立刻用具体事例反驳或贬低自己（如‘数学也就是课本的水平’、‘摄影其实后面还有玩，但是感觉自己没啥天赋’），表现出对积极反馈的抗拒。",
    "（推断）当话题涉及需要与他人比较或评价自身表现时（如提到同学摄影好），会触发来访者强调自己的不足和退缩行为（如‘不愿意跟别人聊天，看到消息也不愿意回复’）。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者渴望摆脱‘自我精神内耗’和‘自我焦虑’带来的失眠、没精打采的痛苦状态。",
    "against_change": "（推断）来访者可能对‘自我贬低’和‘退缩’的自我认知模式有情感上的依恋，将其视为一种自我保护或对现实困难（如工作能力不足）的‘合理’解释。"
  },
  "values_and_stakes": [
    "（推断）改变可能意味着失去‘工作能力不足’这一解释所带来的、来自同事和科长的低期望与特殊关照（如‘科长鼓励我啥的，因为我们招不到人’）。",
    "（推断）改变可能意味着失去‘社牛外向乐观’的旧有自我认同，需要面对和接纳当前‘不愿意跟别人聊天’的社交退缩状态。"
  ],
  "key_facts": [
    "来访者最近因为工作而失眠。",
    "来访者看到[App名]消息也不愿意回复，甚至不知道咋回复。",
    "来访者所在单位的工作同事都说不难，但来访者觉得好难，不会。"
  ]
}

{
  "background": "（推断）来访者是一位有职业经历、可能已为人父母的成年人，近期经历了跳槽等人生转折，正在为家庭和未来奋斗。",
  "self_view_of_problem": "（推断）来访者认为自己的人生经历丰富但充满转折和辛苦，可能感到迷茫或不确定自己的问题究竟是什么，希望从外部获得明确的定义。",
  "resistance_drivers": [
    "当咨询师进行概括性或支持性反馈（如'丰富的人生经历''努力奋斗'）而非直接指出问题时，来访者会表现出不耐烦并要求对方'直说'。",
    "（推断）当感到对话停留在表面认可而非深入剖析时，来访者会主动打断并明确要求指出具体问题，表现出对模糊回应的低容忍度。"
  ],
  "ambivalence": {
    "for_change": "（推断）来访者渴望明确自身问题以获得方向和改变，这种寻求定义的动力推动其参与咨询。",
    "against_change": "（推断）来访者可能对直面自身问题的核心或脆弱部分存在情感上的回避或恐惧，维持现状可避免潜在的自我认知冲击。"
  },
  "values_and_stakes": [
    "（推断）改变可能意味着失去当前对自身'努力奋斗者'身份的认同，以及由此带来的心理安全感。",
    "（推断）深入探讨问题可能威胁到来访者在家庭中作为'为未来考虑'的可靠决策者的角色。"
  ],
  "key_facts": [
    "来访者近期为了孩子的未来选择了跳槽。",
    "来访者主动要求咨询师'直说'并明确询问'我的问题是什么？'。",
    "来访者描述自己的人生是'一段丰富的人生经历'并经历了'很多转折'。"
  ]
}

{
  "background": "（推断）一位经历过创伤性手术的来访者，可能处于术后恢复期或长期受其影响，生活处境涉及与创伤相关的心理调适。",
